 END IF;
 IF b.paused_reason='user_stop' AND p_action IN ('payg_wait','payg_resume','checkpoint_primary','checkpoint_match','checkpoint_source','check_latest',
  'fail_before_dispatch','fail_platform','interrupt','owner_cancel','owner_session','owner_tool') THEN
